const rows = $input.all().map(item => item.json);

// ---------- Helpers ----------
const num = (value) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
};

const parseDate = (value) => {
  const timestamp = Date.parse(String(value ?? '').trim());
  return Number.isFinite(timestamp) ? timestamp : 0;
};

const formatGhanaDate = (iso) => {
  const d = new Date(iso);

  if (Number.isNaN(d.getTime())) {
    return String(iso ?? '');
  }

  return new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Africa/Accra',
    day: '2-digit',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  }).format(d);
};

// ---------- Validation ----------
if (!rows.length) {
  throw new Error('No metrics snapshots found.');
}

// ---------- Latest snapshot ----------
const sorted = [...rows].sort(
  (a, b) => parseDate(b.snapshotAt) - parseDate(a.snapshotAt)
);

const latest = sorted[0];

// ---------- Operational status ----------
let systemStatus = 'HEALTHY';

if (num(latest.overdueLeads) > 0) {
  systemStatus = 'ATTENTION REQUIRED';
}

if (num(latest.aiFailureCount) > 0) {
  systemStatus = 'DEGRADED';
}

const reportDate = formatGhanaDate(latest.snapshotAt);

// ---------- Subject ----------
const emailSubject =
  `CedarLead Daily Operations Report - ${reportDate}`;

// ---------- HTML report ----------
const emailHtml = `
<div style="font-family:Arial,sans-serif;max-width:760px;margin:auto;color:#222;">
  <h2 style="margin-bottom:4px;">CedarLead Daily Operations Report</h2>
  <p style="margin-top:0;color:#666;">
    Snapshot: ${reportDate}
  </p>

  <div style="padding:12px;border:1px solid #ddd;margin:16px 0;">
    <strong>System Status:</strong> ${systemStatus}
  </div>

  <h3>Lead Performance</h3>
  <table cellpadding="8" cellspacing="0" border="1" style="border-collapse:collapse;width:100%;">
    <tr>
      <td>Total Leads</td>
      <td><strong>${num(latest.totalLeads)}</strong></td>
      <td>Average Lead Score</td>
      <td><strong>${num(latest.avgLeadScore)}</strong></td>
    </tr>
    <tr>
      <td>HOT Leads</td>
      <td><strong>${num(latest.hotLeads)}</strong></td>
      <td>WARM Leads</td>
      <td><strong>${num(latest.warmLeads)}</strong></td>
    </tr>
    <tr>
      <td>COLD Leads</td>
      <td><strong>${num(latest.coldLeads)}</strong></td>
      <td>Active Leads</td>
      <td><strong>${num(latest.activeLeads)}</strong></td>
    </tr>
  </table>

  <h3>Lifecycle Pipeline</h3>
  <table cellpadding="8" cellspacing="0" border="1" style="border-collapse:collapse;width:100%;">
    <tr>
      <td>NEW</td>
      <td>${num(latest.newLeads)}</td>
      <td>CONTACTED</td>
      <td>${num(latest.contactedLeads)}</td>
    </tr>
    <tr>
      <td>QUALIFIED</td>
      <td>${num(latest.qualifiedLeads)}</td>
      <td>PROPOSAL</td>
      <td>${num(latest.proposalLeads)}</td>
    </tr>
    <tr>
      <td>WON</td>
      <td>${num(latest.wonLeads)}</td>
      <td>LOST</td>
      <td>${num(latest.lostLeads)}</td>
    </tr>
  </table>

  <h3>SLA & Operational Health</h3>
  <table cellpadding="8" cellspacing="0" border="1" style="border-collapse:collapse;width:100%;">
    <tr>
      <td>Overdue Leads</td>
      <td><strong>${num(latest.overdueLeads)}</strong></td>
      <td>Total Escalations</td>
      <td><strong>${num(latest.totalEscalations)}</strong></td>
    </tr>
    <tr>
      <td>P1 Overdue</td>
      <td>${num(latest.p1Overdue)}</td>
      <td>P2 Overdue</td>
      <td>${num(latest.p2Overdue)}</td>
    </tr>
    <tr>
      <td>P3 Overdue</td>
      <td>${num(latest.p3Overdue)}</td>
      <td></td>
      <td></td>
    </tr>
  </table>

  <h3>AI Health</h3>
  <table cellpadding="8" cellspacing="0" border="1" style="border-collapse:collapse;width:100%;">
    <tr>
      <td>Successful Enrichments</td>
      <td>${num(latest.aiSuccessCount)}</td>
      <td>Failed Enrichments</td>
      <td>${num(latest.aiFailureCount)}</td>
    </tr>
    <tr>
      <td>OpenAI</td>
      <td>${num(latest.openaiCount)}</td>
      <td>Ollama</td>
      <td>${num(latest.ollamaCount)}</td>
    </tr>
    <tr>
      <td>Fallback Count</td>
      <td>${num(latest.aiFallbackCount)}</td>
      <td>Fallback Rate</td>
      <td>${num(latest.aiFallbackRatePct)}%</td>
    </tr>
  </table>

  <p style="margin-top:20px;color:#666;font-size:12px;">
    Generated automatically by CedarLead Monitoring & Reporting.
  </p>
</div>
`;

return [
  {
    json: {
      ...latest,
      reportDate,
      systemStatus,
      emailSubject,
      emailHtml,
      reportGeneratedAt: new Date().toISOString(),
      dailyReportVersion: '1.0',
    },
  },
];
